    20→// Security: Allowlist of valid service names to prevent injection
    21→const ALLOWED_SERVICES = new Set([
    22→    'plex', 'jellyfin', 'emby', 'sonarr', 'radarr', 'prowlarr', 'lidarr',
    23→    'readarr', 'bazarr', 'overseerr', 'tautulli', 'qbittorrent', 'sabnzbd',
    24→    'nzbget', 'transmission', 'deluge', 'gluetun', 'traefik', 'nginx',
    25→    'authelia', 'cloudflared', 'portainer', 'watchtower', 'homepage',
    26→    'homarr', 'organizr', 'flaresolverr', 'recyclarr', 'notifiarr',
    27→    'autobrr', 'unpackerr', 'tdarr', 'handbrake', 'makemkv'
    28→]);
    29→
    30→// Validate service name against allowlist
    31→function validateServiceName(name: string | undefined): { valid: boolean; sanitized?: string; error?: string } {
    32→    if (!name || typeof name !== 'string') {
    33→        return { valid: false, error: 'Service name is required' };
    34→    }
    35→
    36→    const sanitized = name.toLowerCase().trim().replace(/[^a-z0-9_-]/g, '');
    37→
    38→    if (sanitized.length === 0) {
    39→        return { valid: false, error: 'Invalid service name format' };
    40→    }
    41→
    42→    if (sanitized.length > 64) {
    43→        return { valid: false, error: 'Service name too long' };
    44→    }
    45→
    46→    // Check if it matches a known service or follows valid Docker naming
    47→    const isAllowed = ALLOWED_SERVICES.has(sanitized) ||
    48→                      Array.from(ALLOWED_SERVICES).some(s => sanitized.startsWith(s + '_') || sanitized.startsWith(s + '-'));
    49→
    50→    if (!isAllowed) {
    51→        // Allow custom names but log a warning
    52→        logger.warn({ serviceName: sanitized }, 'Service name not in allowlist, proceeding with caution');
    53→    }
    54→
    55→    return { valid: true, sanitized };
    56→}
    57→
    58→// Validate file path to prevent directory traversal
    59→// eslint-disable-next-line @typescript-eslint/no-unused-vars
    60→function validateFilePath(filePath: string | undefined): { valid: boolean; sanitized?: string; error?: string } {
    61→    if (!filePath || typeof filePath !== 'string') {
    62→        return { valid: false, error: 'File path is required' };
    63→    }
    64→
    65→    // Prevent directory traversal attacks
    66→    if (filePath.includes('..') || filePath.includes('\0')) {
    67→        return { valid: false, error: 'Invalid file path: directory traversal not allowed' };
    68→    }
    69→
    70→    const sanitized = filePath.trim();
    71→
    72→    // Only allow relative paths within project
    73→    if (sanitized.startsWith('/') && !sanitized.startsWith(PROJECT_ROOT)) {
    74→        return { valid: false, error: 'Absolute paths outside project root not allowed' };
    75→    }
    76→
    77→    return { valid: true, sanitized };
    78→}
