     6→/**
     7→ * Safely extract error message from an unknown error
     8→ * Replaces the pattern: catch (err: any) { err.message }
     9→ */
    10→export function getErrorMessage(error: unknown): string {
    11→    if (error instanceof Error) {
    12→        return error.message;
    13→    }
    14→    if (typeof error === 'string') {
    15→        return error;
    16→    }
    17→    if (error && typeof error === 'object' && 'message' in error) {
    18→        return String((error as { message: unknown }).message);
    19→    }
    20→    return 'An unknown error occurred';
    21→}
    22→
    23→/**
    24→ * Check if an error has a specific error code
    25→ */
    26→export function hasErrorCode(error: unknown, code: string): boolean {
    27→    if (error && typeof error === 'object' && 'code' in error) {
    28→        return (error as { code: unknown }).code === code;
    29→    }
    30→    return false;
    31→}
    32→
    33→/**
    34→ * Check if error message contains a specific string (case-insensitive)
    35→ */
    36→export function errorContains(error: unknown, text: string): boolean {
    37→    const message = getErrorMessage(error).toLowerCase();
    38→    return message.includes(text.toLowerCase());
    39→}
